const body = $input.first().json.body || {};
const value = body.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];
if (!msg || msg.type !== 'text') return [];
return [{ json: { phone_number_id: value.metadata.phone_number_id, wa_id: msg.from, text: msg.text.body, message_id: msg.id } }];

const ctx = $input.first().json;
const inc = $('Extraire message').first().json;
if (!ctx || !ctx.tenant || !ctx.tenant.active) return [];
const t = ctx.tenant;
const messages = (ctx.history || []).map(m => ({ role: m.role, content: m.content }));
messages.push({ role: 'user', content: inc.text });
while (messages.length && messages[0].role !== 'user') messages.shift();
const system = [
  `Tu es l'assistant virtuel de ${t.business_name}. Tu réponds aux clients sur WhatsApp au nom de l'entreprise.`,
  t.system_prompt || '',
  'BASE DE CONNAISSANCES :',
  t.knowledge_base || '',
  'RÈGLES :',
  '- Réponds en français, en 3 phrases maximum, sans emoji et sans mise en forme markdown.',
  `- Utilise uniquement la base de connaissances. Si l'information manque, indique que la demande est transmise à l'équipe et termine par le marqueur [ESCALADE].`,
  `- N'invente jamais de prix, de délai ni de promesse.`,
  `- Pour un rendez-vous : demande le nom, la date et l'heure souhaitées, puis indique que l'équipe confirme.`
].join('\n');
return [{ json: { system, messages, tenant: t } }];

const r = $input.first().json;
let text = (r.content && r.content[0] && r.content[0].text) ? r.content[0].text.trim() : '';
const inc = $('Extraire message').first().json;
const ctx = $('Construire requête').first().json;
const escalade = text.includes('[ESCALADE]');
text = text.replace('[ESCALADE]', '').trim();
if (!text) return [];
return [{ json: { reply: text, escalade, to: inc.wa_id, phone_number_id: inc.phone_number_id, user_text: inc.text, tenant_id: ctx.tenant.id, wa_token: ctx.tenant.wa_token || $env.WA_TOKEN } }];
